<script setup lang="ts">
import { statusLabels,quoteStatuses,orderStatuses,money,type RequestRecord, type Status } from '@ellas/shared';
definePageMeta({layout:'admin',middleware:'staff'});
const route=useRoute();const {mutate}=useStaff();const url=`/api/admin/requests/${route.params.id}`;
const {data:request,error,refresh}=await useFetch<RequestRecord>(url);
useSeo(request.value?.number || 'Detalle de solicitud','Gestión privada de una solicitud.');
const busy=ref(false);const message=ref('');const failure=ref('');const note=ref('');const status=ref<Status>('recibido');
const prices=ref<(string|number)[]>([]);const personal=ref<string|number>('');const delivery=ref<string|number>('');const tax=ref<string|number>('');const proposalNotes=ref('');
watch(request,value=>{if(!value)return;status.value=value.status;prices.value=value.lines.map((_,i)=>value.proposal?((value.proposal.prices[i]||0)/100).toFixed(2):'');personal.value=value.proposal?(value.proposal.personalizationCents/100).toFixed(2):'';delivery.value=value.proposal?(value.proposal.deliveryCents/100).toFixed(2):'';tax.value=value.proposal?String(value.proposal.taxRate):'';proposalNotes.value=value.proposal?.notes||'';},{immediate:true});
const allowed=computed(()=>request.value?.type==='presupuesto'?quoteStatuses:orderStatuses);
const closed=computed(()=>['aceptado','descartado','entregado','cancelado'].includes(request.value?.status || ''));
const emailLabels:Record<string,string>={pending:'Pendiente de envío',sending:'Enviando',sent:'Aceptado por el proveedor',failed:'Error: reintentos agotados',unconfigured:'Proveedor sin configurar'};
function date(value:string){return new Intl.DateTimeFormat('es-ES',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}
async function act(path:string,method:'POST'|'PATCH'|'PUT',body?:unknown){if(busy.value)return;busy.value=true;failure.value='';message.value='';try{await mutate(url+path,{method,body});await refresh();message.value='Cambios guardados.';return true;}catch(e){failure.value=errorMessage(e);return false;}finally{busy.value=false;}}
async function addNote(){if(await act('/notes','POST',{text:note.value,version:request.value?.version}))note.value='';}
async function saveProposal(){if(!request.value)return;if([...prices.value,personal.value,delivery.value,tax.value].some(v=>String(v).trim()===''||!Number.isFinite(Number(v))||Number(v)<0)){failure.value='Completa todos los importes y el tipo de IVA. Introduce 0 si un concepto no tiene coste.';return;}await act('/proposal','PUT',{prices:prices.value.map(v=>Math.round(Number(v)*100)),personalizationCents:Math.round(Number(personal.value)*100),deliveryCents:Math.round(Number(delivery.value)*100),taxRate:Number(tax.value),notes:proposalNotes.value,version:request.value.version});}
const preview=computed(()=>{if(!request.value)return 0;const subtotal=prices.value.reduce<number>((sum,v,i)=>sum+Math.round((Number(v)||0)*100)*(request.value?.lines[i]?.quantity||0),0)+Math.round((Number(personal.value)||0)*100)+Math.round((Number(delivery.value)||0)*100);return subtotal+Math.round(subtotal*(Number(tax.value)||0)/100);});
</script>
<template><div v-if="error || !request" class="empty-state"><h1>Solicitud no disponible</h1><p>Comprueba el enlace o vuelve al listado.</p><NuxtLink to="/admin/solicitudes" class="button dark">Volver a solicitudes</NuxtLink></div><template v-else><NuxtLink to="/admin/solicitudes" class="text-link admin-back"><AppIcon name="ArrowLeft" :size="16" /> Todas las solicitudes</NuxtLink><div class="admin-title"><div><div class="detail-kicker"><span class="eyebrow">{{request.type.toUpperCase()}} / {{date(request.createdAt)}}</span><span v-if="request.demo||request.isSynthetic" class="demo-data">Datos ficticios de demostración</span></div><h1 class="detail-number">{{request.number}}</h1><p class="fine-print">Origen: {{request.sourceChannel||'web'}} · {{request.environment==='live'?'Registro comercial':'Demostración'}}<span v-if="request.isSynthetic"> · Comprobación ficticia</span></p><p>{{request.contact.company || request.contact.name}} · {{request.lines.reduce((sum,l)=>sum+l.quantity,0)}} prendas</p></div><span class="status-badge" :class="`status-${request.status}`">{{statusLabels[request.status]}}</span></div><div v-if="message" role="status" class="alert success">{{message}}</div><div v-if="failure" role="alert" class="alert error">{{failure}}</div><div class="request-detail-layout"><div><section class="admin-card"><div class="section-heading small"><h2>Prendas de la solicitud</h2><span class="fine-print">Datos conservados al enviar</span></div><div class="table-scroll"><table class="admin-table detail-lines"><thead><tr><th>Prenda</th><th>Color</th><th>Talla</th><th>Uds.</th></tr></thead><tbody><tr v-for="(line,i) in request.lines" :key="i"><td><div class="detail-product"><img :src="line.image" :alt="line.name" width="44" height="55" /><span><b>{{line.reference}}</b><small>{{line.name}}</small></span></div></td><td>{{line.colorName}}<small class="table-secondary">{{line.color}}</small></td><td>{{line.size}}</td><td><b>{{line.quantity}}</b></td></tr></tbody></table></div></section><section class="admin-card"><h2>Personalización y observaciones</h2><template v-if="request.personalization.enabled"><dl class="detail-dl"><dt>Técnica solicitada</dt><dd>{{request.personalization.technique}}</dd><dt>Ubicación</dt><dd>{{request.personalization.placement || 'Por definir'}}</dd></dl><p class="preserve-lines">{{request.personalization.notes || 'Sin detalles adicionales.'}}</p><a v-if="request.personalization.uploadId" :href="`/api/uploads/${request.personalization.uploadId}`" target="_blank" rel="noopener" class="button outline"><AppIcon name="ExternalLink" :size="17" /> Ver logo privado</a></template><p v-else>Sin personalización solicitada.</p><hr /><p v-if="request.desiredDate"><b>Fecha deseada:</b> {{request.desiredDate}}</p><p class="preserve-lines"><b>Observaciones:</b> {{request.notes || 'Sin observaciones.'}}</p></section><section class="admin-card"><div class="section-heading small"><h2>Propuesta económica</h2><span v-if="request.demo||request.isSynthetic" class="demo-data">Importes de ejemplo</span></div><p class="fine-print">Introduce importes unitarios sin IVA en euros. La propuesta se guarda para gestión interna; no se envía automáticamente al cliente.</p><form @submit.prevent="saveProposal"><div class="proposal-lines"><label v-for="(line,i) in request.lines" :key="i"><span><b>{{line.reference}}</b> · {{line.color}} · {{line.size}} <small>{{line.quantity}} uds.</small></span><span class="currency-input"><input v-model="prices[i]" type="number" min="0" step="0.01" :disabled="closed || busy" :aria-label="`Precio unitario ${line.reference}, ${line.color}, ${line.size}`" placeholder="0,00" /><span>€ / ud.</span></span></label></div><div class="form-grid proposal-extras"><label>Personalización (€ sin IVA)<input v-model="personal" type="number" min="0" step="0.01" :disabled="closed || busy" placeholder="Indica el importe" /></label><label>Entrega (€ sin IVA)<input v-model="delivery" type="number" min="0" step="0.01" :disabled="closed || busy" placeholder="Indica el importe" /></label><label>IVA (%)<input v-model="tax" type="number" min="0" max="100" step="0.01" :disabled="closed || busy" placeholder="Indica el tipo aplicable" /></label></div><label>Condiciones y notas<textarea v-model="proposalNotes" maxlength="2000" rows="2" :disabled="closed || busy" /></label><div class="proposal-total"><span>Total propuesto con IVA</span><b>{{money(preview)}}</b></div><button v-if="!closed" class="button dark" type="submit" :disabled="busy">Guardar propuesta <AppIcon name="Check" :size="18" /></button><p v-if="request.proposal" class="fine-print">Última propuesta: {{date(request.proposal.updatedAt)}} · {{request.proposal.by}}</p></form></section><section class="admin-card"><h2>Historial y notas internas</h2><form class="internal-note" @submit.prevent="addNote"><label><span class="sr-only">Nueva nota interna</span><textarea v-model="note" placeholder="Deja una nota para el equipo…" maxlength="2000" rows="3" required /></label><button class="button dark" :disabled="busy || !note.trim()">Añadir nota <AppIcon name="Plus" :size="17" /></button></form><ol class="event-timeline"><li v-for="(event,i) in [...request.events].reverse()" :key="i"><span class="timeline-dot" /><div><p class="preserve-lines">{{event.text}}</p><small>{{event.by}} · {{date(event.at)}}</small></div></li></ol></section></div><aside class="request-sidebar"><section class="admin-card"><h2>Gestionar solicitud</h2><form @submit.prevent="act('/status','PATCH',{status,version:request.version})"><label>Estado<select v-model="status"><option v-for="value in allowed" :key="value" :value="value">{{statusLabels[value]}}</option></select></label><button class="button dark full" :disabled="busy || status===request.status">Guardar estado</button></form><button v-if="request.type==='presupuesto' && request.status==='aceptado'" class="button lime full convert-button" :disabled="busy" @click="act('/convert','POST',{version:request.version})">Convertir en pedido <AppIcon name="ArrowRight" :size="16" /></button><p class="fine-print">La aceptación se registra manualmente tras hablar con el cliente. Conserva su número e historial al convertirlo.</p></section><section class="admin-card"><h2>Datos de contacto</h2><dl class="contact-dl"><dt>Nombre</dt><dd>{{request.contact.name}}</dd><dt>Empresa</dt><dd>{{request.contact.company || '—'}}</dd><dt>Email</dt><dd><a :href="`mailto:${request.contact.email}`">{{request.contact.email}}</a></dd><dt>Teléfono</dt><dd><a :href="`tel:${request.contact.phone}`">{{request.contact.phone}}</a></dd></dl></section><section class="admin-card email-card"><h2><AppIcon name="Mail" :size="19" /> Seguimiento del correo</h2><p v-if="request.demo">El historial ficticio no genera emails.</p><p v-else-if="request.notificationsAllowed===false">No se autorizaron avisos por correo al registrar esta solicitud.</p><template v-else><div v-for="job in request.email" :key="job.role" class="email-job"><b>{{job.role==='business'?'Aviso al negocio':'Confirmación al solicitante'}}</b><span class="status-badge" :class="job.status==='sent'?'status-confirmado':''">{{emailLabels[job.status] || job.status}}</span><small>{{job.attempts}} intentos<span v-if="job.sentAt"> · {{date(job.sentAt)}}</span></small><p v-if="job.lastError" class="field-error">{{job.lastError}}</p><small v-if="job.providerId">ID proveedor: {{job.providerId}}</small></div><p class="fine-print">En demo, ambos correos se redirigen al buzón de desarrollo. «Aceptado por el proveedor» no acredita recepción en el buzón.</p><button class="button outline full" :disabled="busy" @click="act('/email/retry','POST')">Reintentar envíos pendientes</button><button class="text-link" :disabled="busy" @click="refresh()">Actualizar seguimiento <AppIcon name="Clock" :size="15" /></button></template></section></aside></div></template></template>
